CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE activity_events (id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, duration_ms INTEGER NOT NULL, source TEXT NOT NULL, type TEXT NOT NULL, application TEXT NOT NULL, title TEXT NOT NULL, idle INTEGER NOT NULL, metadata TEXT NOT NULL);
CREATE INDEX events_time ON activity_events(timestamp);
CREATE INDEX events_app_time ON activity_events(application,timestamp);
CREATE TABLE activity_sessions (id TEXT PRIMARY KEY, application TEXT NOT NULL, title TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, duration_ms INTEGER NOT NULL, idle INTEGER NOT NULL, source TEXT NOT NULL);
CREATE INDEX sessions_end ON activity_sessions(end);
CREATE INDEX sessions_app_start ON activity_sessions(application,start);
CREATE TABLE conversations (id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX messages_created ON messages(created_at);
CREATE TABLE memories (id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,deadline TEXT,confidence REAL NOT NULL,epistemic_type TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT REFERENCES messages(id) ON DELETE CASCADE,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX memories_state ON memories(status,type);
CREATE TABLE projects (id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE goals (id TEXT PRIMARY KEY REFERENCES memories(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY REFERENCES memories(id) ON DELETE CASCADE,goal_id TEXT REFERENCES goals(id) ON DELETE SET NULL);
CREATE TABLE ideas (id TEXT PRIMARY KEY REFERENCES memories(id) ON DELETE CASCADE);
CREATE TABLE ai_insights (id TEXT PRIMARY KEY,memory_id TEXT REFERENCES memories(id) ON DELETE CASCADE,epistemic_type TEXT NOT NULL,content TEXT NOT NULL,confidence REAL NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE notification_candidates (id TEXT PRIMARY KEY,memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,reason TEXT NOT NULL,confidence REAL NOT NULL,suggested_action TEXT NOT NULL,estimated_effort_minutes INTEGER NOT NULL,score REAL NOT NULL,decision TEXT NOT NULL,explanation TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX candidates_memory_time ON notification_candidates(memory_id,created_at);
CREATE TABLE notifications (id TEXT PRIMARY KEY,candidate_id TEXT NOT NULL REFERENCES notification_candidates(id) ON DELETE CASCADE,memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,content TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,sent_at TEXT,snoozed_until TEXT);
CREATE INDEX notifications_time ON notifications(created_at);
CREATE TABLE notification_events (id TEXT PRIMARY KEY,notification_id TEXT REFERENCES notifications(id) ON DELETE CASCADE,candidate_id TEXT REFERENCES notification_candidates(id) ON DELETE CASCADE,type TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX feedback_time ON notification_events(created_at);
CREATE TABLE user_preferences (user_id TEXT NOT NULL REFERENCES users(id),key TEXT PRIMARY KEY,value TEXT NOT NULL);
